#include <stdio.h>

int main(void) {
    char s[256];
    if (fgets(s, sizeof s, stdin) == NULL) return 1;

    long long tong = 0, tich = 1, so = 0;
    for (int i = 0; s[i] != '\0' && s[i] != '\n'; i++) {
        char c = s[i];
        if (c >= '0' && c <= '9') {
            so = so * 10 + (c - '0');
        } else if (c == '*') {
            tich *= so;
            so = 0;
        } else if (c == '+') {
            tich *= so;
            tong += tich;
            tich = 1;
            so = 0;
        }
    }
    tich *= so;
    tong += tich;
    printf("%lld\n", tong);
    return 0;
}
